const pgState = $('Postgres: Ensure Job Hunter Tables & Seed Vault').first().json || {};
const activePortalSlot = pgState.active_portal_slot || null;
const sentNotifs = new Set(Array.isArray(pgState.sent_notifs) ? pgState.sent_notifs : []);
const eodLogs = Array.isArray(pgState.eod_logs) ? pgState.eod_logs : [];
const existingDrafts = Array.isArray(pgState.followup_drafts) ? pgState.followup_drafts : [];
const emailAlerts = Array.isArray(pgState.email_alerts) ? pgState.email_alerts : [];

const jobRows = $('Read Job Application Sheet').all().map(i => i.json);
const refRows = $('Read Reference Sheet').all().map(i => i.json);

const TG_TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';
const CHAT_ID = '8873019272';
const SHEET_URL = 'https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_DOCUMENT_ID/edit';
const MASTER_RESUME_URL = 'https://drive.google.com/file/d/YOUR_GOOGLE_DRIVE_ID';

const _ctx = this;
async function sendTelegram(text, inlineKeyboard) {
  try {
    if (_ctx && _ctx.helpers && typeof _ctx.helpers.httpRequest === 'function') {
      await _ctx.helpers.httpRequest({
        method: 'POST',
        url: `https://api.telegram.org/bot${TG_TOKEN}/sendMessage`,
        headers: { 'Content-Type': 'application/json' },
        body: {
          chat_id: CHAT_ID,
          text,
          parse_mode: 'Markdown',
          disable_web_page_preview: true,
          ...(inlineKeyboard ? { reply_markup: { inline_keyboard: inlineKeyboard } } : {})
        },
        json: true
      });
      return;
    }
  } catch (e) {}
}

const globalLock = $getWorkflowStaticData('global');
const _nowMs = Date.now();
if (globalLock.wf4RunningUntil && _nowMs < globalLock.wf4RunningUntil) {
  return [{ json: { ok: true, skippedByCollisionGuard: true, shouldTriggerWf1: false, enrichedCount: 0, sheetUpdates: [], newNotifKeys: [], combinedSql: 'SELECT 1;' } }];
}
globalLock.wf4RunningUntil = _nowMs + 25000;
const _istNow = new Date(_nowMs + 5.5 * 3600 * 1000);
const nowIstTimestamp = `${_istNow.toISOString().slice(0, 10)} ${_istNow.toISOString().slice(11, 16)} IST`;

const esc = s => String(s || '').replace(/'/g, "''");
const sqlQueries = [];

// ============================================================================
// 1. Check Incoming Email Payload (if triggered by IMAP Email Trigger on user@example.com)
// ============================================================================
let imapEmailProcessed = null;
try {
  if ($('IMAP Email Trigger (user@example.com)').isExecuted) {
    const mailItem = $('IMAP Email Trigger (user@example.com)').first()?.json || {};
    const subj = String(mailItem.subject || '').trim();
    const fromStr = String(mailItem.from?.text || mailItem.from || '').trim();
    const textBody = String(mailItem.text || mailItem.html || '').replace(/<[^>]+>/g, ' ').slice(0, 500).trim();
    const msgId = String(mailItem.messageId || `imap-${Date.now()}`).trim();

    if (subj || fromStr) {
      const combined = `${subj} ${textBody}`.toLowerCase();
      let category = 'GENERAL_EMAIL';
      let actionTaken = 'Logged in email monitor';
      let compGuess = '';

      if (/interview|schedule a call|shortlist|assessment|hackerrank|testgorilla|hirevue|next steps|recruiter/i.test(combined)) {
        category = 'INTERVIEW_OR_RECRUITER';
        actionTaken = 'Sent urgent Telegram alert';
      } else if (/thank you for applying|application received|application submitted|applied to|application sent/i.test(combined)) {
        category = 'APP_CONFIRMATION';
        actionTaken = 'Confirmed application status';
      } else if (/otp|verification code|security code|passcode/i.test(combined)) {
        category = 'PORTAL_OTP';
        actionTaken = 'Forwarded OTP to Telegram';
      } else if (/job alert|recommended jobs|jobs for you|new jobs|matching your profile/i.test(combined)) {
        category = 'JOB_ALERT';
        actionTaken = 'Queued for deduplicated job evaluation';
      }

      sqlQueries.push(`
        INSERT INTO job_hunter_email_alerts (message_id, sender, subject, category, company_name, snippet, action_taken)
        VALUES ('${esc(msgId)}', '${esc(fromStr)}', '${esc(subj)}', '${esc(category)}', '${esc(compGuess)}', '${esc(textBody.slice(0, 200))}', '${esc(actionTaken)}')
        ON CONFLICT (message_id) DO NOTHING;
      `);

      if (category === 'INTERVIEW_OR_RECRUITER' || category === 'PORTAL_OTP') {
        const otpMatch = textBody.match(/\b(\d{4,8})\b/);
        await sendTelegram(
          `📬 *New ${category === 'PORTAL_OTP' ? 'Portal OTP' : 'Recruiter / Interview'} Email on user@example.com!*\n` +
          `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
          `• *From:* \`${fromStr.slice(0, 80)}\`\n` +
          `• *Subject:* *${subj.slice(0, 120)}*\n` +
          (otpMatch && category === 'PORTAL_OTP' ? `• *Detected OTP Code:* \`${otpMatch[1]}\`\n` : '') +
          `• *Snippet:* _${textBody.slice(0, 220)}..._`,
          [[{ text: '📬 View All 008 Email Alerts', callback_data: 'cmd:check_emails' }], [{ text: '▴ Main Menu', callback_data: 'nav:home' }]]
        );
      }
      imapEmailProcessed = { msgId, subj, fromStr, category };
    }
  }
} catch (e) {}

// Build Reference & Official Company Career Page Map from Reference Sheet (gid=0)
const refByCompany = {};
const refEmailByCompany = {};
const refCareerPageByCompany = {
  'united': 'https://careers.united.com/us/en/c/corporate-jobs',
  'united airlines': 'https://careers.united.com/us/en/c/corporate-jobs',
  'bain': 'https://www.bain.com/careers/find-a-role/?office=gurugram,bengaluru,new-delhi',
  'bain & company (bcn)': 'https://www.bain.com/careers/find-a-role/?office=gurugram,bengaluru,new-delhi',
  '7-eleven global solution center': 'https://careers.7-eleven.com',
  'atlys': 'https://www.atlys.com/careers',
  'orange business': 'https://www.orange-business.com/en/careers',
  'jobgether': 'https://jobgether.com/remote-jobs',
  'siemens energy': 'https://jobs.siemens-energy.com/',
  'damco': 'https://www.damcogroup.com/careers'
};
for (const r of refRows) {
  const comp = String(r['Company'] || '').trim().toLowerCase();
  const refName = String(r['Reference'] || r['Name of the person'] || '').trim();
  const refEmail = String(r['Email of Reference'] || '').trim();
  const careerPage = String(r['Career Page'] || '').trim();
  if (comp && refName) refByCompany[comp] = refName;
  if (comp && refEmail) refEmailByCompany[comp] = refEmail;
  if (comp && careerPage && /^https?:\/\//i.test(careerPage)) {
    refCareerPageByCompany[comp] = careerPage;
  }
}

function getCompanyCareerPage(companyName, fallbackWebsite) {
  const cKey = String(companyName || '').trim().toLowerCase();
  if (cKey && refCareerPageByCompany[cKey]) return refCareerPageByCompany[cKey];
  for (const [k, url] of Object.entries(refCareerPageByCompany)) {
    if (cKey && (cKey.includes(k) || k.includes(cKey))) return url;
  }
  if (fallbackWebsite && /^https?:\/\//i.test(fallbackWebsite)) {
    return `${fallbackWebsite.replace(/\/+$/, '')}/careers`;
  }
  return '';
}

function resolveVacancyOrCompanyCareerUrl(rawUrl, companyName, portalName, channel, fallbackWebsite) {
  const u = String(rawUrl || '').trim();
  const compCareer = getCompanyCareerPage(companyName, fallbackWebsite);
  const pLower = String(portalName || '').toLowerCase();

  // Check if URL is missing, literal 'Link', generic search URL, synthetic Naukri URL without numeric ID, or mismatched portal
  const isMissingOrPlaceholder = !u || u.toLowerCase() === 'link' || !/^https?:\/\//i.test(u);
  const isGenericSearchUrl = /\/jobs\/search|\?keywords=|\/search\?q=|linkedin\.com\/jobs\/search/i.test(u);
  const isSyntheticNaukriWithoutId = /naukri\.com\/job-listings-/i.test(u) && !/-\d{6,15}(\?|$|\/)/.test(u);
  const isPortalMismatch = (
    (pLower.includes('naukri') && /linkedin\.com/i.test(u)) ||
    (pLower.includes('linkedin') && /naukri\.com/i.test(u))
  );
  const isExplicitCompanyReroute = (channel === 'COMPANY_SITE' || channel === 'REROUTED_COMPANY_SITE');

  if (isMissingOrPlaceholder || isGenericSearchUrl || isSyntheticNaukriWithoutId || isPortalMismatch || isExplicitCompanyReroute) {
    return {
      url: compCareer || ( (!isMissingOrPlaceholder && !isGenericSearchUrl) ? u : (fallbackWebsite || SHEET_URL) ),
      isReroutedToCompanySite: true,
      reason: isGenericSearchUrl ? 'generic_search_url' : (isSyntheticNaukriWithoutId ? 'synthetic_portal_slug' : (isPortalMismatch ? 'portal_reroute' : 'company_career_page'))
    };
  }
  return {
    url: u,
    isReroutedToCompanySite: false,
    reason: 'direct_vacancy_url'
  };
}

function inferFromJd(title, jd, existingCompany) {
  const text = `${title}\n${jd}`;
  let company = existingCompany;
  if (!company) {
    if (/american express|aexp/i.test(text)) company = 'American Express';
    else if (/siemens energy/i.test(text)) company = 'Siemens Energy';
    else if (/google/i.test(text)) company = 'Google';
    else if (/stripe/i.test(text)) company = 'Stripe';
    else if (/united airlines/i.test(text)) company = 'United Airlines';
    else if (/atlys/i.test(text)) company = 'Atlys';
    else if (/turing/i.test(text)) company = 'Turing';
  }
  let industry = '';
  if (/databricks|snowflake|confluent|cloud lakehouse/i.test(`${company} ${text}`)) {
    industry = 'Enterprise Data & AI (Cloud Lakehouse)';
  } else if (/fintech|financial|bank|card|payment|american express|stripe|principal|crisil|mastercard|visa|jpmorgan|razorpay|wise/i.test(`${company} ${text}`)) {
    industry = 'Financial Services & FinTech';
  } else if (/\bsiemens energy\b|\brenewable energy\b|\bpower grid\b|\boil and gas\b|\bindustrial\b/i.test(`${company} ${text}`)) {
    industry = 'Energy & Industrial Technology';
  } else if (/travel|airline|priceline|atlys|united|airbnb|makemytrip/i.test(`${company} ${text}`)) {
    industry = 'Travel & Aviation Tech';
  } else if (/real estate|jll|jones lang/i.test(`${company} ${text}`)) {
    industry = 'Commercial Real Estate & Advisory';
  } else if (/consulting|bain|zs|tiger|tredence|latentview|nagarro|ey|axtria/i.test(`${company} ${text}`)) {
    industry = 'Analytics & Strategy Consulting';
  } else if (/retail|7-eleven|ecommerce|flipkart|walmart|target|meesho/i.test(`${company} ${text}`)) {
    industry = 'Retail & E-Commerce';
  } else {
    industry = 'Technology & Data Analytics';
  }

  let location = '';
  if (/gurugram|gurgaon/i.test(text)) location = 'Gurugram (Hybrid)';
  else if (/bengaluru|bangalore/i.test(text)) location = 'Bengaluru';
  else if (/mumbai/i.test(text)) location = 'Mumbai';
  else if (/pune/i.test(text)) location = 'Pune';
  else if (/hyderabad/i.test(text)) location = 'Hyderabad';
  else if (/europe|eu|uk|germany|amsterdam|london/i.test(text)) location = 'EU / Global Remote';
  else if (/australia|sydney|melbourne/i.test(text)) location = 'Australia / Global Remote';
  else if (/remote/i.test(text)) location = 'Remote (India / Global)';
  else location = 'India (Hybrid / Remote)';

  let website = '';
  if (company) {
    const slug = company.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (slug.includes('americanexpress')) website = 'https://www.americanexpress.com';
    else if (slug.includes('siemensenergy')) website = 'https://www.siemens-energy.com';
    else website = `https://www.${slug}.com`;
  }
  const about = company
    ? `${company} is a leading ${industry.toLowerCase()} organization hiring for ${title || 'analytics leadership'}.`
    : '';

  return { company, industry, location, website, about };
}

function formatDateMDY(d) {
  return `${d.getMonth() + 1}/${d.getDate()}/${d.getFullYear()}`;
}

function addDaysMDY(dateStr, days) {
  let base = new Date();
  if (dateStr) {
    const parsed = new Date(dateStr);
    if (!isNaN(parsed.getTime())) base = parsed;
  }
  base.setDate(base.getDate() + days);
  return formatDateMDY(base);
}

// Build set of companies with active HR / Recruiter email threads in user@example.com
const activeHrEmailCompanies = new Set();
for (const ea of emailAlerts) {
  if (ea.category === 'INTERVIEW_OR_RECRUITER') {
    const cName = String(ea.company_name || '').trim().toLowerCase();
    if (cName) activeHrEmailCompanies.add(cName);
    const subjAndFrom = `${ea.subject || ''} ${ea.sender || ''}`.toLowerCase();
    for (const r of jobRows) {
      const jc = String(r['Company'] || '').trim().toLowerCase();
      if (jc && jc.length >= 3 && subjAndFrom.includes(jc)) {
        activeHrEmailCompanies.add(jc);
      }
    }
  }
}

function isPlaceholderHrLabel(hrStr) {
  const s = String(hrStr || '').trim().toLowerCase();
  if (!s) return true;
  return /talent acquisition|risk analytics|internal audit|\bta\b|recruiting team|hr team|hiring team|human resources/i.test(s);
}

// Strict Follow-Up Date Gate:
// ONLY put a Follow up Date when:
// 1. Applying via Reference / Referral (Reference col non-empty or Applied From includes Referral/Reference)
// 2. Resume has been sent to HR (Applied From = Email / HR, or real HR Email / named HR contact present)
// 3. Ongoing conversation with HR over mail (matched in activeHrEmailCompanies or Notes/Status mentions HR mail/reply/interview)
function qualifiesForFollowUpDate(row, patch = {}) {
  const refVal = String(patch['Reference'] !== undefined ? patch['Reference'] : (row['Reference'] || '')).trim();
  const appFrom = String(patch['Applied From'] !== undefined ? patch['Applied From'] : (row['Applied From'] || '')).trim().toLowerCase();
  const hrEmail = String(patch['HR Email'] !== undefined ? patch['HR Email'] : (row['HR Email'] || '')).trim();
  const hrName = String(patch['HR'] !== undefined ? patch['HR'] : (row['HR'] || '')).trim();
  const notes = String(patch['Notes'] !== undefined ? patch['Notes'] : (row['Notes'] || '')).trim().toLowerCase();
  const status = String(patch['Status'] !== undefined ? patch['Status'] : (row['Status'] || '')).trim().toLowerCase();
  const comp = String(patch['Company'] !== undefined ? patch['Company'] : (row['Company'] || '')).trim().toLowerCase();

  const isReferral = Boolean(refVal) || /referral|reference/i.test(appFrom) || /applied via /i.test(notes);
  const isSentToHr = /\b(email|sent to hr|hr mail|direct hr)\b/i.test(appFrom) || (hrEmail.includes('@')) || (!isPlaceholderHrLabel(hrName));
  const hasOngoingHrMail = (comp && activeHrEmailCompanies.has(comp)) || /follow-up email sent|hr conversation|recruiter replied|ongoing mail|interview/i.test(`${notes} ${status}`);

  return Boolean(isReferral || isSentToHr || hasOngoingHrMail);
}

const sheetUpdates = [];
const newNotifKeys = [];
let shouldTriggerWf1 = false;

// Build Strict Deduplication Set across existing Sheet rows & EOD logs
const existingCompanyTitleSet = new Set();
const existingCompanySet = new Set();
const existingJobIdSet = new Set();
let firstEmptySNo = null;
const emptySNoList = [];
let maxNumericSNo = 0;

for (const row of jobRows) {
  const sNo = String(row['S. No.'] || '').trim();
  const numSNo = parseInt(sNo, 10);
  if (!isNaN(numSNo) && numSNo > maxNumericSNo) maxNumericSNo = numSNo;

  const title = String(row['Position - Title'] || '').trim();
  const jd = String(row['Position - Description'] || '').trim();
  const comp = String(row['Company'] || '').trim();
  const status = String(row['Status'] || '').trim();
  const jobId = String(row['Job ID'] || '').trim();

  if (comp && title) {
    existingCompanyTitleSet.add(`${comp.toLowerCase()}::${title.toLowerCase()}`);
    existingCompanySet.add(comp.toLowerCase());
  }
  if (jobId) existingJobIdSet.add(jobId.toLowerCase());

  if (sNo && !title && !jd && !comp && !status) {
    if (firstEmptySNo === null) firstEmptySNo = sNo;
    emptySNoList.push(sNo);
  }
}
function allocateNextSNo() {
  if (emptySNoList.length > 0) {
    return String(emptySNoList.shift());
  }
  maxNumericSNo += 1;
  return String(maxNumericSNo);
}
for (const elog of eodLogs) {
  const c = String(elog.company_name || '').trim().toLowerCase();
  const t = String(elog.position_title || '').trim().toLowerCase();
  if (c && t) existingCompanyTitleSet.add(`${c}::${t}`);
  if (c) existingCompanySet.add(c);
}

// ============================================================================
// 2. Enrich Existing Half-Filled Rows & Send Review / Follow-Up Cards
// ============================================================================
for (const row of jobRows) {
  const sNo = String(row['S. No.'] || '').trim();
  if (!sNo) continue;

  const title = String(row['Position - Title'] || '').trim();
  const jd = String(row['Position - Description'] || '').trim();
  const comp = String(row['Company'] || '').trim();
  const status = String(row['Status'] || '').trim();

  if (!title && !jd && !comp && !status) continue;

  const resStatus = String(row['Resume Status'] || '').trim();
  const resLink = String(row['Resume'] || '').trim();
  const existingResumeId = String(row['Resume_id'] || '').trim();

  if (resStatus === 'Create one') {
    shouldTriggerWf1 = true;
  }

  const isReadyForInit = !existingResumeId && (
    resStatus === 'Create one' ||
    jd.length >= 80
  );

  const patch = { 'S. No.': sNo };
  let changed = false;

  const inferred = inferFromJd(title, jd, comp);
  const finalComp = comp || inferred.company || '';

  if (isReadyForInit) {
    patch['Resume_id'] = `RES-${sNo}`;
    changed = true;

    if (!comp && inferred.company) patch['Company'] = inferred.company;
    if (!String(row['Industry'] || '').trim() && inferred.industry) patch['Industry'] = inferred.industry;
    if (!String(row['Location'] || '').trim() && inferred.location) patch['Location'] = inferred.location;
    if (!String(row['Reference'] || '').trim() && finalComp) {
      const refMatch = refByCompany[finalComp.toLowerCase()];
      if (refMatch) patch['Reference'] = refMatch;
    }
    if (status.toLowerCase() === 'applied') {
      const appDate = String(row['Applied On'] || '').trim() || formatDateMDY(new Date());
      if (!String(row['Applied On'] || '').trim()) patch['Applied On'] = appDate;
      if (!String(row['Follow up Date'] || '').trim() && qualifiesForFollowUpDate(row, patch)) {
        patch['Follow up Date'] = addDaysMDY(appDate, 3);
      }
    }
    if (!String(row['About Company'] || '').trim() && inferred.about) patch['About Company'] = inferred.about;
    if (!String(row['Company website'] || '').trim() && inferred.website) patch['Company website'] = inferred.website;
    if (title && jd.length >= 100 && status.toLowerCase() !== 'applied' && !resStatus && !resLink) {
      patch['Resume Status'] = 'Create one';
      shouldTriggerWf1 = true;
    }
  }

  // Auto-heal Applied Page link if it is a generic search URL, mismatched/rerouted portal slug, or placeholder 'Link'
  const currentAppliedLink = String(row['Applied Page link'] || '').trim();
  const currentAppliedFrom = String(row['Applied From'] || '').trim();
  const currentWebsite = String(row['Company website'] || patch['Company website'] || inferred.website || '').trim();
  if (finalComp) {
    const resolvedLinkInfo = resolveVacancyOrCompanyCareerUrl(
      currentAppliedLink,
      finalComp,
      currentAppliedFrom,
      currentAppliedFrom.toLowerCase().includes('company site') ? 'COMPANY_SITE' : 'IN_PORTAL',
      currentWebsite
    );
    if (
      resolvedLinkInfo.isReroutedToCompanySite &&
      resolvedLinkInfo.url &&
      resolvedLinkInfo.url !== currentAppliedLink &&
      resolvedLinkInfo.url !== SHEET_URL
    ) {
      patch['Applied Page link'] = resolvedLinkInfo.url;
      if (currentAppliedFrom.includes('Auto-Apply') && !currentAppliedFrom.includes('Company Career Site')) {
        const basePortal = currentAppliedFrom.replace(/^🤖\s*Auto-Apply\s*\(([^)]+)\).*$/i, '$1').trim();
        patch['Applied From'] = `🤖 Auto-Apply (${basePortal} → Company Career Site)`;
      }
      changed = true;
      sqlQueries.push(`
        UPDATE job_hunter_eod_log
        SET jd_url = '${esc(resolvedLinkInfo.url)}',
            apply_channel = 'COMPANY_SITE'
        WHERE s_no = '${esc(sNo)}';
      `);
    }
    // Also fix false-positive 'Energy & Industrial Technology' on non-energy companies (caused by 'Tableau' in JD)
    if (
      String(row['Industry'] || '').trim() === 'Energy & Industrial Technology' &&
      !/siemens|energy|power grid|oil/i.test(finalComp)
    ) {
      patch['Industry'] = inferred.industry;
      patch['About Company'] = inferred.about;
      changed = true;
    }
    // Enforce Review-Before-Auto-Apply Rule: if a bot row is still unapproved ('Create one', 'Ready for Review', 'Needs Rework'), hold Status as 'Pending Review' (NOT 'Applied')
    const clStCheck = String(row['Cover Letter Status'] || '').trim();
    const isUnapprovedDraft = (
      ['Create one', 'Ready for Review', 'Needs Rework', 'Generate'].includes(resStatus) ||
      ['Create one', 'Ready for Review', 'Needs Rework', 'Generate'].includes(clStCheck)
    );
    if (isUnapprovedDraft && status.toLowerCase() === 'applied' && (currentAppliedFrom.includes('Auto-Apply') || currentAppliedFrom.includes('Queued'))) {
      patch['Status'] = 'Pending Review';
      patch['Applied On'] = '';
      patch['Follow up Date'] = '';
      patch['Status of Resume and CL'] = 'To be reviewed';
      const cleanPortal = (patch['Applied From'] || currentAppliedFrom).replace(/^🤖\s*Auto-Apply\s*/i, '').replace(/^⏳\s*Queued\s*/i, '').trim();
      patch['Applied From'] = `⏳ Queued ${cleanPortal}`;
      changed = true;
      sqlQueries.push(`DELETE FROM job_hunter_eod_log WHERE s_no = '${esc(sNo)}' AND apply_status = 'Applied';`);
    }
  }

  // Clean up generic placeholder HR team labels (e.g. 'Talent Acquisition Team', 'Risk Analytics & Internal Audit TA')
  const existingHr = String(row['HR'] || '').trim();
  if (existingHr && isPlaceholderHrLabel(existingHr)) {
    patch['HR'] = '';
    changed = true;
  }

  // Enforce strict Follow-Up Date rule on all existing rows:
  // Clear Follow up Date if row is NOT a referral, NOT sent to HR, and has NO ongoing HR email conversation
  const existingFollowUp = String(row['Follow up Date'] || '').trim();
  const qualifiesNow = qualifiesForFollowUpDate(row, patch);
  if (existingFollowUp && !qualifiesNow) {
    patch['Follow up Date'] = '';
    changed = true;
  } else if (!existingFollowUp && qualifiesNow && (status.toLowerCase().includes('applied') || (patch['Status'] || '').toLowerCase().includes('applied'))) {
    const baseDate = String(patch['Applied On'] || row['Applied On'] || '').trim() || formatDateMDY(new Date());
    patch['Follow up Date'] = addDaysMDY(baseDate, 3);
    changed = true;
  }

  if (changed) {
    sheetUpdates.push(patch);
  }

  const resumeId = String(row['Resume_id'] || patch['Resume_id'] || `RES-${sNo}`).trim();
  const pageLink = String(patch['Applied Page link'] || row['Applied Page link'] || '').trim();
  const jdUrlMatch = jd.match(/https?:\/\/[^\s)]+/i);
  const clickableJdUrl = pageLink || (jdUrlMatch ? jdUrlMatch[0] : (String(row['Company website'] || patch['Company website'] || SHEET_URL).trim() || SHEET_URL));
  const refLabel = String(row['Reference'] || patch['Reference'] || 'Direct / Portal').trim();

  if (resStatus === 'Ready for Review' && resLink) {
    const notifKey = `resume_review:${resumeId}:${resLink.slice(-16)}`;
    if (!sentNotifs.has(notifKey)) {
      const msg =
        `📄 *Stage 1: Tailored Resume Ready for Review*\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
