  if (!comp && !title) continue;

  const st = String(row['Status'] || '').trim().toLowerCase();
  const resSt = String(row['Resume Status'] || '').trim().toLowerCase();
  const clSt = String(row['Cover Letter Status'] || '').trim().toLowerCase();
  const resUrl = String(row['Resume'] || '').trim();
  const clUrl = String(row['Cover Letter'] || '').trim();

  if (resSt === 'ready for review' && !st.includes('applied')) {
    readyForReviewCount++;
    readyForReviewRows.push(row);
  }
  if (resSt === 'create one' || resSt === 'generate') {
    createOneCount++;
    shouldTriggerWf1 = true;
  }
  if (
    ['create one', 'ready for review', 'needs rework', 'generate'].includes(resSt) ||
    ['create one', 'ready for review', 'needs rework', 'generate'].includes(clSt) ||
    st === 'pending review' || st === 'pending cl review'
  ) {
    if (!APPROVED_STATES.has(resSt)) {
      pendingReviewCount++;
    }
  }

  const isAlreadyApplied = st.includes('applied') || st.includes('submitted');
  const isResumeApproved = APPROVED_STATES.has(resSt) && resUrl.startsWith('http');
  const isClRequiredOrStarted = clSt !== '' && clSt !== 'not required' && clSt !== 'none';
  const isClApproved = !isClRequiredOrStarted || (APPROVED_STATES.has(clSt) && clUrl.startsWith('http'));

  if (!isAlreadyApplied && isResumeApproved && isClApproved) {
    approvedReadyToApplyRows.push(row);
