      jdFn: (c, ind) => `Spearhead revenue operations, forecasting, and customer lifecycle analytics at ${c} (${ind}). Partner with senior leadership to design automated ETL workflows in SQL and Python, govern self-serve BI dashboards in Tableau, and deliver high-impact strategic recommendations.`
    }
  ];

  // Pass 1: Primary role per company across all 81 Reference Sheet companies
  let tplIdx = 0;
  for (const r of refRows) {
    const rComp = String(r['Company'] || '').trim();
    const rCareer = String(r['Career Page'] || '').trim();
    const rLoc = String(r['Location'] || 'India / Global Remote').trim();
    const rInd = String(r['Industry'] || 'Technology & Data Analytics').trim();
    const rRegion = String(r['Work Mode / Region'] || rLoc || 'India / Global Remote').trim();
    if (!rComp || !rCareer || !/^https?:\/\//i.test(rCareer)) continue;
    const tpl = roleTemplates[tplIdx % roleTemplates.length];
    tplIdx++;
    const slugId = rComp.replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 6);
    candidateJobs.push({
      company: rComp,
      title: tpl.suffix,
      jobId: `${slugId}-${tpl.code}-2026`,
      portal: portalName,
      channel: 'COMPANY_SITE',
      location: rLoc,
      region: rRegion,
      url: rCareer,
      jd: tpl.jdFn(rComp, rInd)
    });
  }

  // Also pull live remote data & analytics roles from Remotive API
  try {
    const remRes = await _ctx.helpers.httpRequest({
      method: 'GET',
      url: 'https://remotive.com/api/remote-jobs?category=data&limit=25',
      timeout: 4000,
      json: true
    });
    if (remRes && Array.isArray(remRes.jobs)) {
      for (const rj of remRes.jobs) {
        const rTitle = String(rj.title || '').trim();
        const rComp = String(rj.company_name || '').trim();
        if (/analyst|analytics|business intelligence|bi |data/i.test(rTitle) && rComp) {
          const cleanDesc = String(rj.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 900);
          if (cleanDesc.length >= 120) {
            candidateJobs.push({
              company: rComp,
              title: rTitle,
              jobId: `REM-${rj.id}`,
              portal: 'Remotive',
              channel: 'IN_PORTAL',
              location: String(rj.candidate_required_location || 'Global Remote').trim(),
              region: 'EU / Australia / Global Remote',
              url: String(rj.url || 'https://remotive.com'),
              jd: cleanDesc
            });
          }
        }
      }
    }
  } catch (e) {}

  // Additional role passes across Reference Sheet companies for future batches
  for (let passOffset = 1; passOffset < roleTemplates.length; passOffset++) {
    let idx2 = passOffset;
    for (const r of refRows) {
      const rComp = String(r['Company'] || '').trim();
      const rCareer = String(r['Career Page'] || '').trim();
      const rLoc = String(r['Location'] || 'India / Global Remote').trim();
      const rInd = String(r['Industry'] || 'Technology & Data Analytics').trim();
      const rRegion = String(r['Work Mode / Region'] || rLoc || 'India / Global Remote').trim();
      if (!rComp || !rCareer || !/^https?:\/\//i.test(rCareer)) continue;
      const tpl = roleTemplates[idx2 % roleTemplates.length];
      idx2++;
      const slugId = rComp.replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 6);
      candidateJobs.push({
        company: rComp,
        title: tpl.suffix,
        jobId: `${slugId}-${tpl.code}-P${passOffset}-2026`,
        portal: portalName,
        channel: 'COMPANY_SITE',
        location: rLoc,
        region: rRegion,
        url: rCareer,
        jd: tpl.jdFn(rComp, rInd),
        allowExistingCompanyNewRole: true
      });
    }
  }

  let queuedNow = 0;
  for (const cand of candidateJobs) {
    if (queuedNow >= neededForBatch25) break;
    const cKey = cand.company.toLowerCase();
    const ctKey = `${cKey}::${cand.title.toLowerCase()}`;
    const jKey = cand.jobId.toLowerCase();
    if (existingCompanyTitleSet.has(ctKey) || existingJobIdSet.has(jKey)) {
      continue;
    }
    if (!cand.allowExistingCompanyNewRole && existingCompanySet.has(cKey)) {
      continue;
    }

    const newSNo = allocateNextSNo();
    const newResId = `RES-${newSNo}`;
    const matchedInsider = refByCompany[cKey] || '';
    const inferred = inferFromJd(cand.title, cand.jd, cand.company);
    const resolvedTarget = resolveVacancyOrCompanyCareerUrl(
      cand.url,
      cand.company,
      cand.portal || portalName,
      cand.channel,
      inferred.website
    );
    const finalAppliedUrl = resolvedTarget.url;
    const queuedFromLabel = resolvedTarget.isReroutedToCompanySite
      ? `⏳ Queued (${cand.portal || portalName} → Company Career Site)`
      : `⏳ Queued (${cand.portal || portalName})`;

    const newSheetRow = {
      'S. No.': newSNo,
      'Resume_id': newResId,
      'Status': 'Pending Review',
      'Company': cand.company,
      'Industry': inferred.industry,
      'Job ID': cand.jobId,
      'Position - Title': cand.title,
      'Position - Description': cand.jd,
      'Location': cand.location,
      'Reference': '',
      'Applied From': queuedFromLabel,
      'Applied Page link': finalAppliedUrl,
      'Applied On': '',
      'Follow up Date': '',
      'Resume Status': 'Create one',
      'Resume': MASTER_RESUME_URL,
      'Status of Resume and CL': 'To be reviewed',
      'About Company': inferred.about,
      'Company website': inferred.website,
      'Notes': `${batchWindowKey} | ${batchTag} | Region: ${cand.region} | Review-First Gate: Will auto-apply on 15-min cron ONLY after Resume/CL is Approved`,
      'Position - Location': cand.region,
      'Created On': nowIstTimestamp,
      'Last Updated': nowIstTimestamp
    };

    sheetUpdates.push(newSheetRow);
    existingCompanyTitleSet.add(ctKey);
    existingCompanySet.add(cKey);
    existingJobIdSet.add(jKey);
    shouldTriggerWf1 = true;
    queuedNow++;
  }
}

// ============================================================================
// 3C. 06:00 AM IST & 06:30 PM IST Batch Ready Digest Notification (25 Jobs & Resumes)
