    `\n\n📊 [Open Job Application Tracker Sheet](${SHEET_URL})\n` +
    `_Review & approve individual resumes via **📝 Pending Reviews**, or tap **✅ Approve All Ready Resumes** below to queue them for the 15-minute Auto-Apply Cron:_`;

  await sendTelegram(digestMsg, [
    [{ text: `📝 Review Individual Drafts (${readyForReviewRows.length})`, callback_data: 'cmd:drafts' }],
    [{ text: `✅ Approve All ${readyForReviewRows.length} Ready Resumes (Queue Auto-Apply)`, callback_data: 'cmd:approve_batch_ready' }],
    [{ text: '📊 Live Pipeline', callback_data: 'cmd:pipeline' }, { text: '▴ Main Menu', callback_data: 'nav:home' }]
  ]);
}

